"""Build the five static itinerary pages from the user's detailed tour content."""
import json,html,re,math
from pathlib import Path
root=Path(__file__).resolve().parents[1];out=root/'dist';tours=json.loads((out/'assets/tour-details.json').read_text());h=html.escape
coords={'Colombo':[79.8612,6.9271],'Negombo':[79.8358,7.2083],'Sigiriya':[80.7603,7.957],'Kandy':[80.6337,7.2906],'Ella':[81.0466,6.8667],'Yala':[81.523,6.372],'Galle':[80.2168,6.0329],'Anuradhapura':[80.4037,8.3114],'Nuwara Eliya':[80.7829,6.9497],'Udawalawe':[80.888,6.438],'Unawatuna':[80.2496,6.0107],'Mirissa':[80.459,5.9485],'Polonnaruwa':[81.0027,7.9403],'Dambulla':[80.651,7.8742],'Haputale':[80.959,6.768],'Belihuloya':[80.787,6.714],'Sinharaja':[80.46,6.405],'Tissamaharama':[81.286,6.279],'Tangalle':[80.795,6.024],'Weligama':[80.429,5.974]}
def project(c):return [320+(c[0]-80.7)*130*math.cos(math.radians(7.8)),25+(9.95-c[1])*130]
geo=json.loads((out/'assets/sri-lanka-outline.geojson').read_text());outline=' '.join('M'+' L'.join(f'{x:.1f},{y:.1f}' for x,y in map(project,ring))+' Z' for poly in geo['geometry']['coordinates'] for ring in poly)
def route_map(t):
 points=[project(coords[s]) for s in t['route']];d=' '.join(('M' if i==0 else 'L')+f'{x:.1f},{y:.1f}' for i,(x,y) in enumerate(points));groups=[]
 for i,(x,y) in enumerate(points):
  group=next((g for g in groups if math.hypot(g['x']-x,g['y']-y)<14),None)
  if group:group['n'].append(str(i+1));group['names'].append(t['route'][i])
  else:groups.append(dict(x=x,y=y,n=[str(i+1)],names=[t['route'][i]]))
 dots=''.join(f'<g><title>{h(" / ".join(g["names"]))}</title><circle cx="{g["x"]:.1f}" cy="{g["y"]:.1f}" r="12"/><text x="{g["x"]:.1f}" y="{g["y"]+3:.1f}" text-anchor="middle">{h("·".join(g["n"]))}</text></g>' for g in groups)
 return f'<svg class="tour-route-svg" viewBox="150 10 350 550" role="img" aria-label="{h(t["name"]+" route: "+" to ".join(t["route"]))}"><path class="tour-land" d="{outline}"/><path class="tour-route-path" d="{d}"/><g class="tour-route-stops">{dots}</g></svg>'
def head(title,description):return f'''<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{h(description)}"><title>{h(title)} — Ceylon Voyagers</title><link rel="stylesheet" href="../style.css?v=journey-planner1"><link rel="stylesheet" href="../tour-pages.css?v=1"><link rel="stylesheet" href="../icons.css?v=1"></head><body class="tour-page">'''
def header():return '''<header class="tour-header"><a href="../#home" class="tour-brand" aria-label="Ceylon Voyagers home"><img src="../assets/ceylon-voyagers-logo.png" alt="Ceylon Voyagers — Let the Tropics Take You" width="4167" height="1458"></a><nav class="tour-nav" aria-label="Tour navigation"><a href="index.html">All journeys</a><a href="../#island-explorer">Explore the island</a><a href="../#about-us">About us</a></nav><a class="button tour-header-cta" href="../#build-your-journey">Build your journey <span>↗</span></a></header>'''
def footer():return '''<footer class="tour-footer tour-wrap"><a href="../#home">CEYLON VOYAGERS <small>Let the Tropics Take You</small></a><a href="index.html">Back to the collection ↗</a></footer><script src="../tour-pages.js?v=1"></script><script src="../icons.js?v=1"></script></body></html>'''
credits={
 'explorer-galle-fort.webp':('Grayswoodsurrey','https://commons.wikimedia.org/wiki/File:Galle_Fort,_Sri_Lanka.JPG','CC BY-SA 4.0','https://creativecommons.org/licenses/by-sa/4.0/'),
 'tour-tea-estate.webp':('Keshani Kaveesha','https://commons.wikimedia.org/wiki/File:Tea_Estate_Nuwara_Eliya.jpg','CC BY-SA 4.0','https://creativecommons.org/licenses/by-sa/4.0/'),
 'tour-sinharaja.webp':('Jesminez','https://commons.wikimedia.org/wiki/File:Thick_foliage_in_the_Sinharaja_Forest_Reserve.jpg','CC BY-SA 4.0','https://creativecommons.org/licenses/by-sa/4.0/'),
 'tour-kandy-offerings.webp':('Ernest Jourdier','https://commons.wikimedia.org/wiki/File:Temple_of_the_Tooth_Kandy.jpg','CC BY 4.0','https://creativecommons.org/licenses/by/4.0/')}
def photo(image,alt,cls='',credit=False):
 caption=''
 if image in credits:
  name,url,license,license_url=credits[image]
  caption=f'<figcaption>Photo: <a href="{url}" target="_blank" rel="noopener noreferrer">{h(name)}</a> · <a href="{license_url}" target="_blank" rel="noopener noreferrer">{license}</a> · resized.</figcaption>'
 return f'<figure class="{cls}"><img src="../assets/{h(image)}" alt="{h(alt)}" loading="lazy" width="1200" height="800">'+caption+'</figure>'
notes=[('Dates & weather','Match the regions and experiences with your travel dates. Beach, surf and wildlife conditions vary across the island.'),('Access & activities','Attraction access, park blocks, guides, vehicle availability, rail seats and optional activities are confirmed during planning.'),('Your pace','Climbs, early starts, walking demands and road transfers can be adjusted around your mobility, interests and comfort.'),('Price & inclusions','No fixed package price, hotel category, meals, guide services or admission tickets are included or confirmed by this outline.'),('Thoughtful travel','Respect sacred places, communities and wildlife. Animal sightings and sea-based activities are never guaranteed.')]
for index,t in enumerate(tours):
 href='../?tour='+t['slug']+'#inquiry';days=[]
 for day in t['days']:
  num=day['day'];highlights=''.join('<span>'+h(v.strip())+'</span>' for v in day['highlights'].split(';'))
  days.append(f'''<details class="tour-day" id="day-{num}" open><summary><span class="tour-day-number">{num:02}</span><span class="tour-day-title"><small>DAY {num:02}</small><strong>{h(day['title'])}</strong></span><span class="tour-day-toggle" aria-hidden="true">+</span></summary><div class="tour-day-body"><p>{h(day['description'])}</p><div class="tour-day-highlights"><span class="tour-meta-label">THE LITTLE HIGHLIGHTS</span><div>{highlights}</div></div><div class="tour-day-night"><span aria-hidden="true">☾</span><div><small>SUGGESTED NIGHT</small><strong>{h(day['overnight'])}</strong></div></div></div></details>''')
 moments=''.join('<article class="tour-moment">'+photo(m['image'],m['title']+' — Sri Lanka travel inspiration','tour-moment-photo',m['image']=='explorer-galle-fort.webp')+f'<span>{h(m["category"])}</span><h3>{h(m["title"])}</h3></article>' for m in t['moments'])
 route=''.join(f'<li><span>{i+1:02}</span>{h(stop)}</li>' for i,stop in enumerate(t['route']))
 related=''.join(f'<a class="tour-related-card" href="{o["slug"]}.html"><img src="../assets/{o["hero"]}" alt="" loading="lazy"><div><small>{o["duration"]} DAYS · {h(o["pace"].upper())}</small><h3>{h(o["name"])}</h3><span>Discover this journey ↗</span></div></a>' for o in [tours[(index+1)%5],tours[(index+2)%5]])
 page=head(t['name']+' · '+str(t['duration'])+' days',t['description'])+header()+f'''<main><section class="tour-hero"><img class="tour-hero-image" src="../assets/{h(t['hero'])}" alt="Sri Lanka — {h(t['pace'].lower())} journey" width="1600" height="1000" fetchpriority="high"><div class="tour-hero-shade"></div><div class="tour-wrap tour-hero-copy"><div class="tour-breadcrumb"><a href="../#home">Home</a><span>/</span><a href="index.html">Our journeys</a><span>/</span><span>Journey {index+1:02}</span></div><p class="tour-kicker">{h(t['tag'])}</p><h1>{h(t['name'])}</h1><p class="tour-hero-description">{h(t['description'])}</p><a class="button tour-primary" href="{href}">Make this journey mine <span>↗</span></a></div><div class="tour-hero-bottom tour-wrap"><span>CEYLON VOYAGERS / SIGNATURE JOURNEY {index+1:02}</span><a href="#day-by-day">A little more discovery ↓</a></div></section><div class="tour-wrap"><div class="tour-facts"><div><span>YOUR TIME</span><strong>{t['duration']} days</strong></div><div><span>THE FEEL</span><strong>{h(t['pace'])}</strong></div><div><span>THE APPROACH</span><strong>Made flexible</strong></div><p>A suggested journey.<br>Shaped around you.</p></div><section class="tour-moments" aria-labelledby="moments-heading"><p class="tour-kicker">MOMENTS TO MAKE ROOM FOR</p><h2 id="moments-heading">A few reasons to fall for this journey.</h2><div class="tour-moments-grid">{moments}</div><p class="tour-photo-note">Images offer a glimpse of Sri Lanka’s landscapes and experiences; individual stops and conditions may differ.</p></section><div class="tour-content-layout"><aside class="tour-route-card" aria-labelledby="tour-route-heading"><div class="tour-route-top"><p class="tour-kicker">YOUR ISLAND ROUTE</p><h2 id="tour-route-heading">One place.<br>Then another.</h2></div><div class="tour-route-visual">{route_map(t)}</div><p class="tour-map-note">Route overview · lines connect stops, not driving directions. Nearby stops may share a marker.</p><ol class="tour-route-list">{route}</ol><a class="button tour-route-cta" href="{href}">Tailor this route <span>↗</span></a></aside><section class="tour-timeline" id="day-by-day" aria-labelledby="tour-days-heading"><div class="tour-timeline-heading"><p class="tour-kicker">{t['duration']} DAYS. YOUR KIND OF DISCOVERY.</p><h2 id="tour-days-heading">Every day,<br>a new perspective.</h2><p>A day-by-day starting point, with room for the moments you never planned.</p><button class="tour-toggle-days" type="button">Collapse all days −</button></div>{''.join(days)}<p class="tour-daily-note">Suggested pacing and overnight areas. Day order and stops can change with arrival times, weather, access and your preferred pace.</p></section></div><section class="tour-planning" aria-labelledby="tour-planning-heading"><div><p class="tour-kicker">THE LITTLE DETAILS MATTER</p><h2 id="tour-planning-heading">Thoughtfully planned.<br>Ready to make yours.</h2><p>This is a flexible trip concept, rather than a confirmed departure or booking. We’ll shape the practical details around your dates and preferences.</p></div><div class="tour-planning-notes">{''.join(f'<details><summary>{h(a)}<span aria-hidden="true">+</span></summary><p>{h(b)}</p></details>' for a,b in notes)}</div></section><section class="tour-enquiry-callout"><div><p class="tour-kicker">YOUR NEXT CHAPTER</p><h2>This route.<br>Your rhythm.</h2><p>Tell us what you love, what you’d change, and when you’d like to go.</p></div><a class="button tour-primary" href="{href}">Plan this journey <span>↗</span></a></section><section class="tour-related" aria-labelledby="related-heading"><p class="tour-kicker">FOLLOW ANOTHER FEELING</p><h2 id="related-heading">A different way to see the island.</h2><div class="tour-related-grid">{related}</div><a class="tour-back" href="index.html">Explore all five journeys ↗</a></section></div></main>'''+footer()
 (out/'tours'/f'{t["slug"]}.html').write_text(page)
cards=''.join(f'''<a class="collection-card" href="{t['slug']}.html"><div class="collection-photo"><img src="../assets/{t['hero']}" alt="" width="1200" height="800" loading="lazy"><span>{t['duration']} DAYS</span></div><div class="collection-copy"><p class="tour-kicker">{h(t['tag'])}</p><h2>{h(t['name'])}</h2><p>{h(t['description'])}</p><span class="collection-route">{' · '.join(h(x) for x in dict.fromkeys(t['route']) if x!='Colombo')}</span><strong>View full itinerary <span>↗</span></strong></div></a>''' for t in tours)
page=head('Five signature journeys','Explore five detailed Sri Lanka itineraries, from heritage and tea country to wildlife and the south coast.')+header()+'''<main class="tour-collection"><section class="collection-intro tour-wrap"><a href="../#itineraries" class="tour-back">← Back to the island</a><p class="tour-kicker">FIVE WAYS TO FALL FOR THE ISLAND</p><h1>Sri Lanka,<br><em>one journey at a time.</em></h1><p>Choose the feeling. Discover the details.<br>Make the journey your own.</p></section><section class="collection-grid tour-wrap" aria-label="All five itineraries">'''+cards+'''</section><div class="collection-note tour-wrap"><p>These are suggested, flexible journeys. Dates, stays, transport, activities and pricing are confirmed during personalised planning.</p><a class="button tour-primary" href="../#build-your-journey">Build your own journey <span>↗</span></a></div></main>'''+footer();(out/'tours/index.html').write_text(page)
print('Built five itinerary pages and the collection page, containing',sum(len(t['days']) for t in tours),'daily plans.')
